/**
 * P4d session 1: the zh lexicon for zh-vi (content/zh/lexicon/lexemes.json, generated by
 * content/zh/_drafts/_generators/zh-lex.py) — what the generic lexicon validator does not check.
 */
import { describe, expect, test } from "bun:test";

import { richLexiconSchema, type PackSource } from "../../content/schema";
import { hanCount, isPinyinSyllable, stripTone } from "../lib/cjk-readings/pinyin";
import { readJson } from "../lib/pipeline";

const lexicon = richLexiconSchema("zh").parse(readJson("content/zh/lexicon/lexemes.json"));
type Subset = { hsk: Record<string, [string, string, string, string, string][]>; cedict: Record<string, [string, string, boolean][]> };
const subset = readJson("content/zh/lexicon/derived/hsk-course.json") as Subset;

describe("zh lexicon (P4d)", () => {
  test("about 900 lexemes, every one with a Vietnamese gloss, a pinyin reading, a traditional spelling and a translated example", () => {
    expect(lexicon.lexemes.length).toBeGreaterThanOrEqual(800);
    expect(lexicon.lexemes.length).toBeLessThanOrEqual(950);
    for (const lex of lexicon.lexemes) {
      expect(lex.glosses.vi?.trim().length, lex.id).toBeGreaterThan(0);
      expect(lex.glosses.vi, lex.id).not.toMatch(/^TODO/);
      expect(lex.reading?.pinyin, lex.id).toBe(lex.pronunciation?.value);
      expect(lex.pronunciation?.notation, lex.id).toBe("pinyin");
      const syllables = (lex.reading?.pinyin ?? "").split(" ");
      expect(syllables.length, lex.id).toBe(hanCount(lex.surface));
      for (const s of syllables) expect(isPinyinSyllable(stripTone(s).base), `${lex.id} ${s}`).toBe(true);
      expect([...(lex.reading?.traditional ?? "")].length, lex.id).toBe([...lex.surface].length);
      for (const ex of lex.examples) expect(ex.translations.vi, lex.id).toBeTruthy();
    }
  });

  test("ids are toneless pinyin slugs", () => {
    for (const lex of lexicon.lexemes) expect(lex.id, lex.surface).toMatch(/^zh:w:[a-z0-9]+(?:-[a-z0-9]+)*$/);
  });

  test("every reading is a CC-CEDICT reading of the surface (or a chain of entries for a set phrase)", () => {
    let whole = 0;
    for (const lex of lexicon.lexemes) {
      const entries = subset.cedict[lex.surface];
      if (entries === undefined) continue;
      whole += 1;
      expect(entries.some(([trad, py]) => py === lex.reading?.pinyin && trad === lex.reading?.traditional), lex.surface).toBe(true);
    }
    expect(whole).toBeGreaterThan(lexicon.lexemes.length - 20);
  });

  test("every zh-en word is a lexeme with the pack's English gloss", () => {
    const pack = readJson("content/courses/zh-en.json") as PackSource;
    const bySurface = new Map(lexicon.lexemes.map((l) => [l.surface, l] as const));
    for (const w of pack.sections.flatMap((s) => s.units.flatMap((u) => u.words))) {
      expect(bySurface.get(w.target)?.glosses.en, w.target).toBe(w.native);
    }
  });

  test("HSK 3.0 anchor: most of level 1 and a large part of level 2 are taught", () => {
    const surfaces = new Set(lexicon.lexemes.map((l) => l.surface));
    const share = (level: string) => {
      const words = new Set(subset.hsk[level]!.map((r) => r[1]));
      return [...words].filter((w) => surfaces.has(w)).length / words.size;
    };
    expect(share("1")).toBeGreaterThan(0.8);
    expect(share("2")).toBeGreaterThan(0.4);
  });

  test("every Hán-Việt entry of zh is a lexeme surface or a P4b pair, and names are never given one", () => {
    const table = readJson("content/hanviet/zh.json") as { entries: { word: string }[] };
    const surfaces = new Set(lexicon.lexemes.map((l) => l.surface));
    const proper = new Set(lexicon.lexemes.filter((l) => l.proper).map((l) => l.surface));
    expect(table.entries.filter((e) => surfaces.has(e.word)).length).toBeGreaterThanOrEqual(180);
    for (const e of table.entries) expect(proper.has(e.word), e.word).toBe(false);
  });
});
